// Shared definition of the 3 documented Interactive Video sample projects, used by both
// the regeneration script (scripts/generate-interactive-video-samples.mjs) and the drift
// test (tests/unit/interactive-video-samples.test.js) so the two can never silently
// disagree about what a sample's input configuration was — same reasoning
// tests/fixtures/export-fixture-definitions.mjs already established for export fixtures.

import { COMPONENT_REGISTRY, getComponentById, getDefaultConfig } from '../../js/component-registry.js';
import { buildProject } from '../../js/storage.js';
import { BUILT_IN_THEMES, DEFAULT_THEME_ID } from '../../js/themes.js';

const theme = BUILT_IN_THEMES.find(item => item.id === DEFAULT_THEME_ID);
const entry = getComponentById(COMPONENT_REGISTRY, 'interactive-video');
if (!entry) throw new Error('interactive-video is not registered.');

// The same clip components/interactive-video.js's own defaultConfig already uses — short,
// freely usable, nothing to license. Not a stand-in for real footage: an author importing
// a sample is expected to replace this with their own video before publishing.
