// Deterministic id/dates: a fresh build must byte-for-byte match the committed file (the
// drift test's whole point), so nothing here may vary run-to-run the way
// buildProject()'s own `id`/`createdAt` defaults (createProjectId(), Date.now()) would.
const FIXED_CREATED_AT = '2026-01-01T00:00:00.000Z';

export function buildSampleProject(sample) {
  const config = { ...baseFields, ...getDefaultConfig(entry), ...sample.overrides };
  return buildProject({
    id: `interactive-video-sample-${sample.filename.replace('.json', '')}`,
    name: sample.name,
    componentId: 'interactive-video',
    createdAt: FIXED_CREATED_AT,
    config,
    activeTheme: theme,
    componentOverrides: {},
    uiTheme: 'light',
    settings: undefined
  });
}
